//! `RESULTS.md`: the runs side by side, one table per scenario, each figure the median of
//! its repetitions.

use std::collections::BTreeMap;
use std::fmt::Write;
use std::path::Path;

use serde_json::Value;

use crate::record::{Record, read};

/// The servers, in the order the tables show them.
const SERVERS: [&str; 4] = ["rust", "elixir", "elixir-concurrent", "elixir-upsert"];

pub fn write(out: &Path) {
    let records = read(out);
    let mut md = String::new();
    md.push_str("# Cybercab: Rust vs Elixir\n\n");
    md.push_str(
        "Generated by `cybercab-bench report` from `results.jsonl`. Every figure is the median of \
         its repetitions. Latencies are in milliseconds; `elixir-concurrent` writes the heartbeat \
         as concurrent `report` updates, `elixir-upsert` as one `bulk_create` upsert; reads and \
         commands run on `elixir-concurrent` only, since they don't depend on the heartbeat. \
         `vs rust` is each Elixir figure over Rust's: above 1× is more requests or events for \
         throughput, and slower for latencies.\n\n",
    );
    let reps = records.iter().map(|r| r.rep + 1).max().unwrap_or(0);
    let _ = writeln!(md, "Repetitions: {reps}.\n");

    let grouped = medians(&records);
    table(&mut md, &grouped, "boot", "Boot: start to healthy, seed included", &["fleet"], &[
        ("seconds", &["boot_s"], 2),
    ]);
    table(&mut md, &grouped, "reads", "A. Reads, while the fleet moves", &["fleet", "query", "concurrency"], &[
        ("req/s", &["requests_per_s"], 0),
        ("p50", &["latency_ms", "p50"], 2),
        ("p95", &["latency_ms", "p95"], 2),
        ("p99", &["latency_ms", "p99"], 2),
        ("failed", &["failed"], 0),
    ]);
    table(&mut md, &grouped, "commands", "B. Commands, while the fleet moves", &["fleet", "kind", "concurrency"], &[
        ("req/s", &["requests_per_s"], 0),
        ("p50", &["latency_ms", "p50"], 2),
        ("p95", &["latency_ms", "p95"], 2),
        ("p99", &["latency_ms", "p99"], 2),
        ("failed", &["failed"], 0),
    ]);
    table(&mut md, &grouped, "sim", "C. Simulation: ticks against their 1 s budget", &["fleet"], &[
        ("tick p50", &["ticks", "tick_ms", "p50"], 1),
        ("tick p95", &["ticks", "tick_ms", "p95"], 1),
        ("ticks/s", &["ticks", "ticks_per_s"], 2),
        ("over 1 s", &["ticks", "over_budget"], 0),
        ("CPU cores", &["resources", "cpu_cores"], 2),
        ("peak RSS MB", &["resources", "peak_rss_mb"], 0),
    ]);
    table(&mut md, &grouped, "fanout", "D. Fan-out: the fleet's movements to subscribers", &["subscribers", "fleet"], &[
        ("events/s each", &["events_per_s_per_subscriber"], 0),
        ("delivery p50", &["delivery_ms", "p50"], 0),
        ("delivery p95", &["delivery_ms", "p95"], 0),
        ("ended", &["ended"], 0),
        ("tick p95", &["ticks", "tick_ms", "p95"], 0),
        ("CPU cores", &["resources", "cpu_cores"], 2),
        ("peak RSS MB", &["resources", "peak_rss_mb"], 0),
    ]);
    table(&mut md, &grouped, "room", "E. The real room: simulation, displays and operators at once", &["fleet", "operators", "displays"], &[
        ("read p50", &["read_ms", "p50"], 1),
        ("read p95", &["read_ms", "p95"], 1),
        ("command p50", &["command_ms", "p50"], 1),
        ("command p95", &["command_ms", "p95"], 1),
        ("tick p95", &["ticks", "tick_ms", "p95"], 0),
        ("delivery p95", &["delivery_ms", "p95"], 0),
        ("CPU cores", &["resources", "cpu_cores"], 2),
        ("peak RSS MB", &["resources", "peak_rss_mb"], 0),
    ]);

    std::fs::write(out.join("RESULTS.md"), md).expect("RESULTS.md");
}

type Grouped = BTreeMap<(String, String), BTreeMap<String, Value>>;

/// `(scenario, params) → server → metrics`, each number the median over repetitions.
fn medians(records: &[Record]) -> Grouped {
    let mut runs: BTreeMap<(String, String, String), Vec<&Value>> = BTreeMap::new();
    let mut params_of: BTreeMap<(String, String), Value> = BTreeMap::new();
    for record in records {
        let key = record.params.to_string();
        params_of.insert((record.scenario.clone(), key.clone()), record.params.clone());
        runs.entry((record.scenario.clone(), key, record.server.clone()))
            .or_default()
            .push(&record.metrics);
    }
    let mut grouped = Grouped::new();
    for ((scenario, params, server), metrics) in runs {
        grouped
            .entry((scenario, params))
            .or_default()
            .insert(server, median_of(&metrics));
    }
    grouped
}

fn median_of(values: &[&Value]) -> Value {
    match values.first() {
        Some(Value::Number(_)) => {
            let mut numbers: Vec<f64> = values.iter().filter_map(|v| v.as_f64()).collect();
            numbers.sort_by(f64::total_cmp);
            numbers.get(numbers.len() / 2).copied().map(Value::from).unwrap_or(Value::Null)
        }
        Some(Value::Object(first)) => Value::Object(
            first
                .keys()
                .map(|key| {
                    let children: Vec<&Value> = values.iter().filter_map(|v| v.get(key)).collect();
                    (key.clone(), median_of(&children))
                })
                .collect(),
        ),
        Some(other) => (*other).clone(),
        None => Value::Null,
    }
}

type Column<'a> = (&'a str, &'a [&'a str], usize);

fn table(md: &mut String, grouped: &Grouped, scenario: &str, title: &str, keys: &[&str], columns: &[Column]) {
    let rows: Vec<_> = grouped.iter().filter(|((s, _), _)| s == scenario).collect();
    if rows.is_empty() {
        return;
    }
    let servers: Vec<&str> = SERVERS
        .iter()
        .copied()
        .filter(|server| rows.iter().any(|(_, by_server)| by_server.contains_key(*server)))
        .collect();
    let _ = writeln!(md, "## {title}\n");
    // One table per column, servers across, so each figure sits beside its counterparts.
    for (name, path, decimals) in columns {
        let _ = write!(md, "**{name}**\n\n| {} |", keys.join(" | "));
        for server in &servers {
            let _ = write!(md, " {server} |");
        }
        if servers.contains(&"rust") && servers.len() > 1 {
            md.push_str(" vs rust |");
        }
        md.push('\n');
        let _ = write!(md, "|{}", "---|".repeat(keys.len()));
        md.push_str(&"---:|".repeat(servers.len() + usize::from(servers.contains(&"rust") && servers.len() > 1)));
        md.push('\n');
        let mut sorted = rows.clone();
        sorted.sort_by_key(|((_, params), _)| {
            let params: Value = serde_json::from_str(params).unwrap_or_default();
            keys.iter()
                .map(|k| match &params[*k] {
                    Value::Number(n) => format!("{:>12}", n.as_f64().unwrap_or(0.0) as i64),
                    other => other.to_string(),
                })
                .collect::<Vec<_>>()
        });
        for ((_, params), by_server) in sorted {
            let params: Value = serde_json::from_str(params).unwrap_or_default();
            let _ = write!(md, "| {} |", keys.iter().map(|k| plain(&params[*k])).collect::<Vec<_>>().join(" | "));
            let figure = |server: &str| {
                by_server.get(server).and_then(|m| dig(m, path))
            };
            for server in &servers {
                let cell = figure(server).map(|v| format!("{v:.decimals$}")).unwrap_or_else(|| "–".into());
                let _ = write!(md, " {cell} |");
            }
            if servers.contains(&"rust") && servers.len() > 1 {
                // Each Elixir figure against Rust's.
                let rust = figure("rust");
                let ratios: Vec<String> = servers
                    .iter()
                    .filter(|s| **s != "rust")
                    .filter_map(|s| match (figure(s), rust) {
                        (Some(e), Some(r)) if r > 0.0 => Some(format!("{:.2}×", e / r)),
                        _ => None,
                    })
                    .collect();
                let _ = write!(md, " {} |", if ratios.is_empty() { "–".into() } else { ratios.join(" / ") });
            }
            md.push('\n');
        }
        md.push('\n');
    }
}

fn dig(value: &Value, path: &[&str]) -> Option<f64> {
    path.iter().try_fold(value, |v, key| v.get(*key))?.as_f64()
}

fn plain(value: &Value) -> String {
    match value {
        Value::String(s) => s.clone(),
        Value::Null => "–".into(),
        other => other.to_string(),
    }
}

/// The figures each scenario is judged by, for comparing runs.
/// A figure's name, and where it is in a run's metrics.
type Figure = (&'static str, &'static [&'static str]);

const HEADLINES: &[(&str, &[Figure])] = &[
    ("boot", &[("boot s", &["boot_s"])]),
    ("reads", &[("req/s", &["requests_per_s"]), ("p50", &["latency_ms", "p50"]), ("p95", &["latency_ms", "p95"])]),
    ("commands", &[("req/s", &["requests_per_s"]), ("p50", &["latency_ms", "p50"]), ("p95", &["latency_ms", "p95"])]),
    ("sim", &[
        ("tick p50", &["ticks", "tick_ms", "p50"]),
        ("tick p95", &["ticks", "tick_ms", "p95"]),
        ("CPU", &["resources", "cpu_cores"]),
    ]),
    ("fanout", &[
        ("delivery p50", &["delivery_ms", "p50"]),
        ("delivery p95", &["delivery_ms", "p95"]),
        ("CPU", &["resources", "cpu_cores"]),
    ]),
    ("room", &[
        ("read p95", &["read_ms", "p95"]),
        ("command p95", &["command_ms", "p95"]),
        ("tick p95", &["ticks", "tick_ms", "p95"]),
        ("delivery p95", &["delivery_ms", "p95"]),
    ]),
];

/// One server's figures from two runs, side by side, with the change.
pub fn compare(before: &Path, after: &Path, server: &str) -> String {
    let (before, after) = (medians(&read(before)), medians(&read(after)));
    let mut md = "| scenario | setting | figure | before | after | change |\n|---|---|---|---:|---:|---:|\n".to_string();
    for ((scenario, params), by_server) in &after {
        let (Some(new), Some(old)) = (
            by_server.get(server),
            before.get(&(scenario.clone(), params.clone())).and_then(|b| b.get(server)),
        ) else {
            continue;
        };
        let Some((_, figures)) = HEADLINES.iter().find(|(s, _)| s == scenario) else {
            continue;
        };
        let setting: Value = serde_json::from_str(params).unwrap_or_default();
        let setting = setting
            .as_object()
            .map(|o| o.iter().map(|(k, v)| format!("{k}={}", plain(v))).collect::<Vec<_>>().join(" "))
            .unwrap_or_default();
        for (name, path) in *figures {
            if let (Some(b), Some(a)) = (dig(old, path), dig(new, path)) {
                let change = if b != 0.0 { format!("{:+.0}%", (a - b) / b * 100.0) } else { "–".into() };
                let _ = writeln!(md, "| {scenario} | {setting} | {name} | {b:.2} | {a:.2} | {change} |");
            }
        }
    }
    md
}
